package co.aplomo.soporte;
import co.aplomo.dao.*;import co.aplomo.db.Sql;import co.aplomo.modelo.*;import co.aplomo.servicio.*;import java.nio.file.*;import java.time.*;import java.util.*;import java.io.*;import javax.imageio.ImageIO;
/** RF-024: dos empresas, todos los estados de reserva y un Rojo En curso oculto al Usuario. Todo pertenece a la transacción de BasePrueba. */
public final class EscenarioConsultas {
    public final int empresaA,empresaB,sedeA,sedeB,salonA,salonB,areaA,areaB,cargoA,cargoB,puesto1,puesto2,puesto3,puestoB,visitaFinal,visitaAbierta,visitaB,evalVerde,evalRojo,evalAbierta,evalNuevaAbierta,evalB,pendienteAbierto,pendienteB,sugerenciaAbierta,sugerenciaB,reservaFinal,reservaAbierta,reservaEsperando,reservaCancelada,reservaB;
    public final Evaluaciones evaluaciones;public final Consultas consultas;
    /** Crea únicamente datos nuevos dentro de la conexión reversible recibida. */
    public EscenarioConsultas(BasePrueba b,Path fotos)throws Exception{
        ReglasSugerenciasPrueba.cargar(b.con);empresaA=b.empresa;var empresas=new Empresas(b.tx);var reservas=new Reservas(b.tx,b.reloj);var visitas=new Visitas(b.tx,b.reloj);evaluaciones=new Evaluaciones(b.tx,b.reloj,new Fotos(fotos),new BitacoraDao());consultas=evaluaciones.consultas();
        b.dao.contrasena(b.con,b.usuario,b.cuenta(b.usuario).hash(),false);
        var salon=b.crearSalon();salonA=salon.id();sedeA=salon.sede();areaA=empresas.guardar(b.cuenta(b.admin),new Area(0,empresaA,"Producción y ensamble",true)).id();cargoA=empresas.guardar(b.cuenta(b.admin),new Cargo(0,empresaA,"Operario de precisión","OPERATIVO",true)).id();
        puesto1=puesto(b,empresas,salonA,areaA,cargoA,1,"Estación de ensamble Alfa");puesto2=puesto(b,empresas,salonA,areaA,cargoA,2,"Estación nueva en curso");puesto3=puesto(b,empresas,salonA,areaA,cargoA,3,"Estación de ensamble Zeta");
        reservaFinal=reservas.guardar(b.cuenta(b.admin),0,b.solicitud(salon));reservas.aceptar(b.cuenta(b.admin),reservaFinal);visitaFinal=visitas.iniciar(b.cuenta(b.admin),reservaFinal);
        evalVerde=evaluar(b,visitaFinal,puesto1,1);evalRojo=evaluar(b,visitaFinal,puesto3,10);visitas.finalizar(b.cuenta(b.admin),visitaFinal,"Visita finalizada de prueba");
        b.reloj.avanzar(Duration.ofDays(1));reservaAbierta=reservas.guardar(b.cuenta(b.admin),0,solicitud(empresaA,salon,11));reservas.aceptar(b.cuenta(b.admin),reservaAbierta);visitaAbierta=visitas.iniciar(b.cuenta(b.admin),reservaAbierta);evalAbierta=evaluar(b,visitaAbierta,puesto1,10);evalNuevaAbierta=evaluar(b,visitaAbierta,puesto2,10);
        reservaEsperando=reservas.guardar(b.cuenta(b.admin),0,solicitud(empresaA,salon,13));reservaCancelada=reservas.guardar(b.cuenta(b.admin),0,solicitud(empresaA,salon,15));reservas.cancelar(b.cuenta(b.admin),reservaCancelada,"La empresa solicitó otro horario.");
        empresaB=Sql.insertar(b.con,"INSERT INTO empresa (id_administrador,nombre,nit) VALUES (?,?,?)",b.admin,"Empresa ajena QA",UUID.randomUUID().toString().substring(0,20));b.empresa=empresaB;var otro=b.crearSalon();salonB=otro.id();sedeB=otro.sede();areaB=empresas.guardar(b.cuenta(b.admin),new Area(0,empresaB,"Área ajena QA",true)).id();cargoB=empresas.guardar(b.cuenta(b.admin),new Cargo(0,empresaB,"Cargo ajeno QA","ADMINISTRATIVO",true)).id();puestoB=puesto(b,empresas,salonB,areaB,cargoB,1,"Puesto ajeno QA");
        reservaB=reservas.guardar(b.cuenta(b.admin),0,b.solicitud(otro));reservas.aceptar(b.cuenta(b.admin),reservaB);visitaB=visitas.iniciar(b.cuenta(b.admin),reservaB);evalB=evaluar(b,visitaB,puestoB,10);visitas.finalizar(b.cuenta(b.admin),visitaB,"");b.empresa=empresaA;
        pendienteAbierto=new PendienteDao().porEvaluacion(b.con,evalAbierta).id();pendienteB=new PendienteDao().porEvaluacion(b.con,evalB).id();sugerenciaAbierta=evaluaciones.sugerencias().listar(b.cuenta(b.admin),evalAbierta).get(0).sugerencia().id();sugerenciaB=evaluaciones.sugerencias().listar(b.cuenta(b.admin),evalB).get(0).sugerencia().id();
    }
    private int evaluar(BasePrueba b,int visita,int puesto,int caso)throws Exception{var bytes=new ByteArrayOutputStream();ImageIO.write(new java.awt.image.BufferedImage(12,12,1),"png",bytes);return evaluaciones.guardar(b.cuenta(b.admin),visita,new Evaluaciones.Datos(puesto,"Postura de ensamble "+puesto,"MAS_INADECUADA","Postura mantenida al trabajar.",120,true,true,true,true,true,true,"",true,false),List.of(new Fotos.Entrada(bytes.toByteArray(),"PERFIL","Imagen sintética de prueba")),List.of(new Analisis.Solicitud(0,CasosRulaPrueba.todos().get(caso-1).entrada())));}
    private static int puesto(BasePrueba b,Empresas e,int salon,int area,int cargo,int numero,String nombre)throws Exception{return e.guardar(b.cuenta(b.admin),new Puesto(0,salon,area,cargo,numero,nombre,"MESA","Junto a la ventana",null,true)).id();}
    private Reservas.Datos solicitud(int empresa,Salon salon,int hora){return new Reservas.Datos(empresa,salon.sede(),salon.id(),LocalDate.of(2026,11,11),LocalTime.of(hora,0),LocalTime.of(hora+1,0),"SEGUIMIENTO","Reserva de prueba","");}
}
